BEGIN;
SET LOCAL ROLE service_role;
DO $$
DECLARE actor uuid:=gen_random_uuid();outsider uuid:=gen_random_uuid();r jsonb;second jsonb;reserved jsonb;verified jsonb;changed jsonb;other_proof jsonb;bad text;
BEGIN
 INSERT INTO auth.users(id) VALUES(actor),(outsider);INSERT INTO public.user_roles VALUES(actor,'admin');
 BEGIN PERFORM public.redirect_domain_resource('list',outsider);RAISE EXCEPTION 'Non-owner saw registry';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 IF NOT public.redirect_domain_destination('https://8.8.8.8/path','links.example.com') THEN RAISE EXCEPTION 'Public IPv4 destination rejected';END IF;
 r:=public.redirect_domain_resource('create',actor,p_values=>'{"hostname":"links.example.com","rootUrl":"https://example.org/home"}');
 IF r->>'ownershipState'<>'pending' OR (r->>'ownershipVerified')::boolean OR (r->>'providerConnected')::boolean OR r#>>'{verification,name}'<>'_qg-redirect.links.example.com' THEN RAISE EXCEPTION 'Registry incorrectly ready or missing proof';END IF;
 IF length(r#>>'{verification,value}')<>76 THEN RAISE EXCEPTION 'Weak challenge';END IF;
 BEGIN PERFORM public.redirect_domain_resource('create',actor,p_values=>'{"hostname":"links.example.com"}');RAISE EXCEPTION 'Duplicate hostname accepted';EXCEPTION WHEN unique_violation THEN NULL;END;
 FOREACH bad IN ARRAY ARRAY['queer.guide','go.queer.guide','test.local','127.0.0.1','a..com','https://example.com','go.supabase.co'] LOOP
  BEGIN PERFORM public.redirect_domain_resource('create',actor,p_values=>jsonb_build_object('hostname',bad));RAISE EXCEPTION 'Invalid hostname accepted: %',bad;EXCEPTION WHEN check_violation THEN NULL;END;
 END LOOP;
 second:=public.redirect_domain_resource('create',actor,p_values=>'{"hostname":"other.example.com"}');
 changed:=public.redirect_domain_resource('list',actor,p_limit=>1);
 other_proof:=public.redirect_domain_resource('list',actor,p_limit=>1,p_after=>(changed->>'nextCursor')::uuid);
 IF (changed->>'count')::int<>2 OR jsonb_array_length(changed->'data')<>1 OR changed->>'nextCursor' IS NULL OR jsonb_array_length(other_proof->'data')<>1 OR other_proof->>'nextCursor' IS NOT NULL OR changed#>>'{data,0,id}'=other_proof#>>'{data,0,id}' THEN RAISE EXCEPTION 'Domain paging repeated/skipped rows';END IF;
 IF r#>>'{verification,value}'=second#>>'{verification,value}' THEN RAISE EXCEPTION 'Challenges reused';END IF;
 FOREACH bad IN ARRAY ARRAY['http://127.0.0.1/x','http://999.1.1.1/x','http://test.local/x','https://user:secret@example.com/','https://links.example.com/','https://other.example.com/','/help','https://queer.guide/go/test'] LOOP
  BEGIN PERFORM public.redirect_domain_resource('patch',actor,(r->>'id')::uuid,jsonb_build_object('version',r->>'version','rootUrl',bad));RAISE EXCEPTION 'Invalid/loop destination accepted: %',bad;EXCEPTION WHEN invalid_parameter_value THEN NULL;END;
 END LOOP;
 reserved:=public.redirect_domain_resource('reserve',actor,(r->>'id')::uuid,jsonb_build_object('version',r->>'version'));
 changed:=public.redirect_domain_resource('reserve',actor,(r->>'id')::uuid,jsonb_build_object('version',r->>'version'));
 IF (changed->>'retryAfter')::int NOT BETWEEN 1 AND 60 THEN RAISE EXCEPTION 'DNS cooldown missing';END IF;
 verified:=public.redirect_domain_check_result(actor,(r->>'id')::uuid,(r->>'version')::uuid,(reserved->>'attempt')::uuid,'verified');
 IF NOT (verified->>'ownershipVerified')::boolean OR (verified->>'providerConnected')::boolean THEN RAISE EXCEPTION 'Ownership did not remain separate from routing';END IF;
 BEGIN PERFORM public.redirect_domain_check_result(actor,(r->>'id')::uuid,(r->>'version')::uuid,(reserved->>'attempt')::uuid,'verified');RAISE EXCEPTION 'DNS result replay accepted';EXCEPTION WHEN unique_violation THEN NULL;END;
 BEGIN PERFORM public.redirect_domain_resource('patch',actor,(r->>'id')::uuid,jsonb_build_object('version',r->>'version','disabled',true));RAISE EXCEPTION 'Stale settings overwrite accepted';EXCEPTION WHEN unique_violation THEN NULL;END;
 changed:=public.redirect_domain_resource('rotate',actor,(r->>'id')::uuid,jsonb_build_object('version',verified->>'version'));
 IF (changed->>'ownershipVerified')::boolean OR changed#>>'{verification,value}'=r#>>'{verification,value}' THEN RAISE EXCEPTION 'Rotation preserved old proof';END IF;
 UPDATE public.redirect_domains SET next_check_at=now()-interval '1 second' WHERE id=(r->>'id')::uuid;
 reserved:=public.redirect_domain_resource('reserve',actor,(r->>'id')::uuid,jsonb_build_object('version',changed->>'version'));
 changed:=public.redirect_domain_resource('patch',actor,(r->>'id')::uuid,jsonb_build_object('version',changed->>'version','notFoundUrl','https://example.org/404','expiredUrl','https://example.org/expired'));
 BEGIN PERFORM public.redirect_domain_check_result(actor,(r->>'id')::uuid,(reserved#>>'{domain,version}')::uuid,(reserved->>'attempt')::uuid,'verified');RAISE EXCEPTION 'Edit race applied DNS proof';EXCEPTION WHEN unique_violation THEN NULL;END;
 IF changed->>'rootUrl'<>'https://example.org/home' THEN RAISE EXCEPTION 'Patch erased omitted fields';END IF;
 UPDATE public.redirect_domains SET next_check_at=now()-interval '1 second' WHERE id=(r->>'id')::uuid;
 reserved:=public.redirect_domain_resource('reserve',actor,(r->>'id')::uuid,jsonb_build_object('version',changed->>'version'));
 UPDATE public.redirect_domains SET next_check_at=now()-interval '1 second' WHERE id=(r->>'id')::uuid;
 BEGIN PERFORM public.redirect_domain_check_result(actor,(r->>'id')::uuid,(changed->>'version')::uuid,(reserved->>'attempt')::uuid,'verified');RAISE EXCEPTION 'Old DNS observation accepted';EXCEPTION WHEN unique_violation THEN NULL;END;
 reserved:=public.redirect_domain_resource('reserve',actor,(second->>'id')::uuid,jsonb_build_object('version',second->>'version'));
 other_proof:=public.redirect_domain_check_result(actor,(second->>'id')::uuid,(second->>'version')::uuid,(reserved->>'attempt')::uuid,'verified');
 UPDATE public.redirect_domains SET next_check_at=now()-interval '1 second' WHERE id=(second->>'id')::uuid;
 reserved:=public.redirect_domain_resource('reserve',actor,(second->>'id')::uuid,jsonb_build_object('version',other_proof->>'version'));
 second:=public.redirect_domain_check_result(actor,(second->>'id')::uuid,(other_proof->>'version')::uuid,(reserved->>'attempt')::uuid,'unavailable');
 IF NOT (second->>'ownershipVerified')::boolean OR second->>'verifiedUntil'<>other_proof->>'verifiedUntil' THEN RAISE EXCEPTION 'Transient DNS failure extended or erased existing proof';END IF;
 UPDATE public.redirect_domains SET verified_until=now()-interval '1 second',next_check_at=now()-interval '1 second' WHERE id=(second->>'id')::uuid;
 IF (public.redirect_domain_resource('get',actor,(second->>'id')::uuid)->>'ownershipVerified')::boolean THEN RAISE EXCEPTION 'Expired proof still current';END IF;
 reserved:=public.redirect_domain_resource('reserve',actor,(second->>'id')::uuid,jsonb_build_object('version',second->>'version'));
 second:=public.redirect_domain_check_result(actor,(second->>'id')::uuid,(second->>'version')::uuid,(reserved->>'attempt')::uuid,'missing');
 IF second->>'ownershipState'<>'lost' OR (second->>'ownershipVerified')::boolean THEN RAISE EXCEPTION 'Definite missing proof did not suspend ownership';END IF;
 UPDATE public.redirect_report_budgets SET attempts=30 WHERE bucket='domain-check:'||actor::text;
 UPDATE public.redirect_domains SET next_check_at=now()-interval '1 second' WHERE id=(second->>'id')::uuid;
 reserved:=public.redirect_domain_resource('reserve',actor,(second->>'id')::uuid,jsonb_build_object('version',second->>'version'));
 IF (reserved->>'retryAfter')::int NOT BETWEEN 1 AND 3600 THEN RAISE EXCEPTION 'Owner DNS budget absent';END IF;
 UPDATE public.redirect_domains SET provider_id='fixture-provider' WHERE id=(second->>'id')::uuid;
 BEGIN PERFORM public.redirect_domain_resource('delete',actor,(second->>'id')::uuid,jsonb_build_object('version',second->>'version'));RAISE EXCEPTION 'Provider hostname orphaned';EXCEPTION WHEN invalid_parameter_value THEN NULL;END;
 second:=public.redirect_domain_resource('patch',actor,(second->>'id')::uuid,jsonb_build_object('version',second->>'version','disabled',true));
 BEGIN PERFORM public.redirect_domain_resource('reserve',actor,(second->>'id')::uuid,jsonb_build_object('version',second->>'version'));RAISE EXCEPTION 'Disabled domain checked DNS';EXCEPTION WHEN invalid_parameter_value THEN NULL;END;
 DELETE FROM public.user_roles WHERE user_id=actor;
 BEGIN PERFORM public.redirect_domain_resource('get',actor,(r->>'id')::uuid);RAISE EXCEPTION 'Revoked owner read registry';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
 INSERT INTO public.user_roles VALUES(actor,'admin');
 changed:=public.redirect_domain_resource('delete',actor,(r->>'id')::uuid,jsonb_build_object('version',changed->>'version'));
 IF (public.redirect_domain_resource('list',actor,p_limit=>1)->>'count')::int<>1 THEN RAISE EXCEPTION 'Domain delete/list count incorrect';END IF;
END $$;
RESET ROLE;
SET LOCAL ROLE authenticated;
DO $$ BEGIN
 IF has_function_privilege(current_user,'public.redirect_domain_resource(text,uuid,uuid,jsonb,integer,uuid)','execute') OR has_function_privilege(current_user,'public.redirect_domain_check_result(uuid,uuid,uuid,uuid,text)','execute') THEN RAISE EXCEPTION 'Private registry RPC exposed';END IF;
 BEGIN PERFORM * FROM public.redirect_domains;RAISE EXCEPTION 'Domain challenges exposed';EXCEPTION WHEN insufficient_privilege THEN NULL;END;
END $$;
ROLLBACK;
